/** autogenerated **/
Ext._define('rh.pvf.shiftmanager.Manage', {
    extend: 'toolkit.widget.TabPanel',

    Grid: function(cfg) {
        if(!this._grid) {
            this._grid = Ext._create('rh.pvf.shiftmanager.Grid', {
                region: 'center',
                gridAutoLoad: true
            });
        }
        permissions = cfg.permissions.replaceAll("'",'"')
        permissions = JSON.parse(permissions)
        this._grid.setParam('permissions', permissions);

        return this._grid;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Controle de plantões'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.Grid(cfg),
                ]
            }
        );

        rh.pvf.shiftmanager.Manage.superclass.constructor.call(this, cfg);
    }
});

